  "。它逐项映射全部 506 个 CSS 组件和 66 种 DOM 行为，同时提供 538 个根运行时导出、22 个 TypeScript 类型导出、 29 个公共包入口与 28 个组件 CSS 包代理。": ". Asigna los 506 componentes CSS y 66 comportamientos DOM elemento por elemento, al tiempo que proporciona 538 exportaciones de tiempo de ejecución raíz, 22 exportaciones de tipo TypeScript, 29 puntos de entrada de paquetes públicos y 28 proxies de paquetes CSS de componentes.",
