  "白色画布、中性色文本、4px 基础圆角、克制阴影。圆角和强层次必须显式选择，不会污染普通业务页面。": "Lienzo blanco, texto neutro, esquinas redondeadas básicas de 4 píxeles, sombra restringida. Las esquinas redondeadas y una jerarquía fuerte deben seleccionarse explícitamente y no contaminarán las páginas comerciales ordinarias.",
  "版本、发行说明、延后/重启更新": "Versión, notas de la versión, posponer/reiniciar actualizaciones",
  "版本对比": "Comparación de versiones",
  "版本时间线、当前版本和恢复": "Cronología de la versión, versión actual y recuperación",
  "版本线作为只读兼容别名保留；旧": "Línea de versión reservada como alias compatible de solo lectura; viejo",
  "帮助": "Ayuda",
  "帮助、状态、语言和登录等辅助入口": "Entradas auxiliares como ayuda, estado, idioma e inicio de sesión",
  "帮助说明": "Instrucciones de ayuda",
  "帮助系统": "Sistema de ayuda",
  "帮助中心": "Centro de ayuda",
  "绑定 Electron 安全桥与销毁周期": "Ciclo de seguridad y de destrucción de Electron",
  "绑定 Tauri 窗口按钮与销毁周期": "Botón de ventana de vinculación de Tauri y ciclo de destrucción",
  "绑定行为并访问实例": "Comportamiento de vinculación y acceso a instancias",
  "包裹；容器小于 768px 会独立折叠，不受浏览器窗口宽度干扰。": "Envoltura; Los contenedores de menos de 768 px se colapsarán de forma independiente, independientemente del ancho de la ventana del navegador.",
  "包含每一项，适合 AI 和构建工具直接读取。": "Contiene todos los elementos adecuados para la lectura directa mediante IA y herramientas de construcción.",
  "包明确支持 Node.js >=18.18、Chrome/Edge/Firefox 100+、Safari/iOS 15.4+ 和 ESM；主入口及桌面适配器提供条件": "El paquete admite explícitamente Node.js >=18.18, Chrome/Edge/Firefox 100+, Safari/iOS 15.4+ y ESM; El portal principal y el adaptador de escritorio proporcionan condiciones.",
  "包入口": "Entrada de paquete",
  "包入口可在服务端安全导入，全部 506 个组件均经过逐项 SSR，行为只在 Effect 生命周期内初始化；服务端标记 Hydration 不产生 recoverable error，并兼容 StrictMode。Tauri 与 Electron 分别使用": "La entrada del paquete se puede importar de forma segura en el lado del servidor. Los 506 componentes han pasado por SSR elemento por elemento y el comportamiento solo se inicializa durante el ciclo de vida del Efecto; la marca del lado del servidor Hydration no genera errores recuperables y es compatible con StrictMode. Tauri y Electron se utilizan respectivamente.",
  "保持兼容，可继续作为业务级壳使用。": "Sigue siendo compatible y se puede seguir utilizando como shell de nivel empresarial.",
  "保持为外部 peer dependency，不会把它打进 Gardener 产物，也不会掩盖框架级风险。新项目优先选择 Vue、React 或框架无关入口；存量项目必须同时执行输入净化、CSP、资源白名单、桌面桥最小授权和迁移计划。完整要求见": "Manténgalo como una dependencia de pares externa, que no lo incluye en el producto Gardener y no cubre riesgos a nivel de marco. A los nuevos proyectos se les da prioridad para elegir Vue, React o entradas independientes del marco; Los proyectos existentes también deben implementar desinfección de insumos, CSP, listas blancas de recursos, autorización mínima del puente de escritorio y plan de migración. Para conocer los requisitos completos, consulte",
  "保存": "Guardar",
  "保存草稿": "Guardar borrador",
  "保存成功": "Guardado exitosamente",
  "保存每次正式构建的 raw、gzip、Brotli、压缩比例及 npm 包体积结果。": "Guarde los resultados sin formato, gzip, Brotli, relación de compresión y volumen del paquete npm de cada compilación oficial.",
  "保存前可以通过预览检查所有设备宽度。": "Todos los anchos de los dispositivos se pueden verificar mediante vista previa antes de guardarlos.",
  "保存筛选、排序和列配置": "Guardado de filtros, clasificación y configuraciones de columnas",
  "保护。": "Protección.",
  "保护按钮、链接与输入": "Proteger botones, enlaces y entradas",
  "保护账号": "Proteger cuenta",
  "保留 AngularJS 原生表单模型或桥接自定义组件值": "Preservar el modelo de formulario nativo de AngularJS o unir valores de componentes personalizados",
  "保留 Gardener 类、属性、children 与 Ref": "Conservar clase, propiedades, hijos y referencia de Gardener",
  "保留 Gardener 类、属性与插槽": "Preserve Gardener clase, propiedades y ranuras",
  "保留空轨位置，适合固定卡槽；min / gap": "Mantener la posición del riel vacío, adecuada para fijar la ranura de la tarjeta; min / brecha",
  "报告与发票": "Informes y Facturas",
  "暴露 beforeapproval、beforeclose、beforefilepicker、beforeopen、beforepromptstop、beforepromptsubmit、beforetabclose 7 个必须在 JS/.NET 异步边界前同步阻止的守卫事件。行为成员与事件 detail 契约可从": "Beforeapproval, beforeclose, beforefilepicker, beforeopen, beforepromptstop, beforepromptsubmit, beforetabclose 7 eventos de protección expuestos que deben bloquearse sincrónicamente antes de los límites asincrónicos de JS/.NET. Los miembros de comportamiento y los contratos detallados del evento están disponibles en",
  "暴露全部 75 个事件，": "Exponer los 75 eventos,",
  "本节是给最终用户使用的 AI 产品 UI；后文": "Esta sección es para la interfaz de usuario del producto de IA para usuarios finales; el siguiente texto",
  "本模块不声明可检索的公开项。": "Este módulo no declara elementos públicos con capacidad de búsqueda.",
