  "标签、分段/选择、全屏对话框、Snackbar": "Etiquetas, Segmentación/Selección, Diálogo de pantalla completa, Snackbar",
  "标签、分栏、Dock、检查器和状态栏都保持高密度、小圆角和完整键盘路径。": "Las etiquetas, las columnas, el Dock, el inspector y la barra de estado mantienen alta densidad, pequeñas esquinas redondeadas y rutas de teclado completas.",
