  "标题和操作分居两端并可换行；gap / align": "El título y la acción están separados en ambos extremos y pueden ajustarse; brecha / alinear",
  "标题栏、活动栏、工作台、检查器与状态栏。": "Barra de título, barra de actividad, banco de trabajo, inspector y barra de estado.",
