  "表达 Dirty、Saving、Saved 和 Error，并支持延迟保存及立即保存。": "Expresa Sucio, Guardado, Guardado y Error, y admite guardados retrasados e inmediatos.",
  "表单、导航、浮层、数据、媒体、商业、通信、法律、工作流和 Dashboard 均有稳定结构与状态约定。": "Los formularios, la navegación, las superposiciones, los datos, los medios, los negocios, las comunicaciones, el ámbito jurídico, el flujo de trabajo y el panel tienen estructuras estables y convenciones estatales.",
