  "不是缩小桌面，而是完整的移动应用层": "No es una computadora de escritorio más pequeña, sino una capa de aplicación móvil completa",
  "不要再为下一张页面重新发明基础设施。": "Deje de reinventar la infraestructura para la página siguiente.",
  "不要在 Renderer 开启 Node Integration，也不要向页面暴露任意 IPC。适配器只接受 minimize、maximize、close、drag 白名单动作。": "No habilite la integración de nodos en el renderizador y no exponga ningún IPC a la página. El adaptador solo acepta acciones de minimizar, maximizar, cerrar y arrastrar a la lista blanca.",
  "不遮挡内容的补充优先使用 Help Text、Inline Hint 或 Tip；必须绑定控件时使用 Tooltip；包含链接和操作时使用 Help Popover；跨步骤教学使用 Tour。不要把重要错误或必须阅读的法律信息藏进悬浮层。": "Utilice texto de ayuda, sugerencia en línea o sugerencia para contenido complementario que no bloquee el contenido; utilice información sobre herramientas cuando los controles deban estar vinculados; utilice Help Popover cuando incluya enlaces y operaciones; Utilice Tour para la enseñanza de pasos cruzados. No oculte errores importantes ni información legal de lectura obligatoria en una capa flotante.",
  "布局": "Diseño",
  "布局、表单、导航、数据、内容、账号、商业、移动、桌面和 AI 均可独立引入。": "El diseño, los formularios, la navegación, los datos, el contenido, las cuentas, el comercio, los dispositivos móviles, el escritorio y la IA se pueden introducir de forma independiente.",
  "布局使用逻辑属性，组件覆盖 RTL 下的动画方向与箭头。": "El diseño utiliza propiedades lógicas y los componentes anulan la dirección de la animación y las flechas en RTL.",
