  "初始化根节点自身及其后代的全部行为。": "Inicializa todo el comportamiento del propio nodo raíz y sus descendientes.",
  "处理复杂 CustomEvent。值会转换为 .NET 字符串、布尔、数字、数组或字典；DOM、File、BigInt、函数和循环引用会安全序列化。": "Manejo de eventos personalizados complejos. Los valores se convierten a cadenas .NET, booleanos, números, matrices o diccionarios; DOM, Archivo, BigInt, funciones y referencias circulares se serializan de forma segura.",
  "处理拖入深度、键盘激活和真实文件事件；": "Maneja la profundidad de arrastre, la activación del teclado y eventos de archivos reales;",
