  "触控 · 安全区 · 双栏": "Toque · Área Segura · Doble Columna",
  "触控目标在 Coarse Pointer 环境至少 44px；所有手势组件保留按钮或键盘路径。": "Los objetivos táctiles en entornos de puntero grueso tienen al menos 44 píxeles; Todos los componentes de gestos conservan las rutas de los botones o del teclado.",
