  "窗口 Chrome、导航、编辑区、状态区和宿主桥接各有独立契约。": "La ventana Chrome, la navegación, el área de edición, el área de estado y el puente de host tienen contratos independientes.",
  "创建标准内部部件，避免破坏 CSS 和行为选择器契约。": "Cree componentes internos estándar para evitar romper los contratos de selector de comportamiento y CSS.",
