  "从": "Desde",
  "从 52 个成品结构中选择最接近的页面骨架。": "Seleccione el esqueleto de página más cercano entre 52 estructuras terminadas.",
  "从第一次登录，到每一次安全审计": "Desde el primer inicio de sesión hasta cada auditoría de seguridad",
  "从第一行 CSS 到几十万套 AI 生成模板，这里描述 Gardener 的稳定接口、选择顺序、环境矩阵和交付边界。": "Desde la primera línea de CSS hasta cientos de miles de conjuntos de plantillas generadas por IA, aquí hay una descripción de la interfaz estable, el orden de selección, la matriz del entorno y los límites de entrega de Gardener.",
  "从静态 SSR 到桌面 WebView，使用同一套 Razor 组件": "De SSR estático a WebView de escritorio usando el mismo conjunto de componentes Razor",
  "从看见商品，到交易与退款完成": "Desde ver el producto hasta completar la transacción y reembolso",
  "从逻辑 inline-start 方向偏移": "Desplazamiento desde la dirección lógica de inicio en línea",
  "从企业站主导航到 CMS 树，从移动底栏到 Electron Activity Bar，从右键菜单到 Scrollspy，38 种稳定模式让 AI 直接按意图选择。": "Desde la navegación del propietario del sitio empresarial hasta el árbol CMS, desde la barra inferior móvil hasta Electron Activity Bar, desde el menú de clic derecho a Scrollspy, 38 modos estables permiten a AI seleccionar directamente de acuerdo con la intención.",
  "从上传一个文件，到完成整套内容生产": "Desde subir un archivo hasta completar toda la producción del contenido",
  "从上下主区、左右栏到 Holy Grail、Master / Detail、Dock、可调分栏和全屏工作区，Web、移动端与 Tauri / Electron 直接选用，不必临时编写页面级布局 CSS。": "Desde las áreas principales superior e inferior, las columnas izquierda y derecha hasta el Santo Grial, Maestro/Detalle, Dock, columnas ajustables y espacio de trabajo de pantalla completa, web, terminales móviles y Tauri/Electron se pueden seleccionar directamente sin tener que escribir temporalmente CSS de diseño a nivel de página.",
