  "定义高频页面根类、所有必要部件、适用平台、行为、桌面适配器和用途。它不是截图模板，而是可换主题、可响应、可继续组合的稳定结构。以下展开项保留每个配方的全部字段。": "Define la clase raíz de la página de alta frecuencia, todos los componentes necesarios, las plataformas aplicables, los comportamientos, los adaptadores de escritorio y el uso. No es una plantilla de captura de pantalla, sino una estructura estable que se puede convertir en temas, responde y se puede combinar continuamente. La siguiente expansión conserva todos los campos de cada receta.",
