  "对话": "Diálogo",
  "对话、Composer 与流式回答之外，还需要推理摘要、工具调用和批准、多 Agent 编排、来源引用、Artifact、上下文记忆、Token/费用、语音、权限、隐私、安全复核与反馈评估。Gardener 将整条 AI 任务链做成可直接复用的32种模式。": "Además del diálogo, también se requieren respuestas del compositor y de transmisión, resumen de razonamiento, invocación y aprobación de herramientas, orquestación de múltiples agentes, cita de fuentes, artefacto, memoria contextual, token/tarifa, voz, permisos, privacidad, revisión de seguridad y evaluación de comentarios. Gardener convierte toda la cadena de tareas de IA en 32 modos que se pueden reutilizar directamente.",
