  "返回、标题与尾部动作": "Acciones de retorno, título y cola",
  "返回的 packed、unpacked 和文件数。1.0.0 以封版的 0.9.0 实测结果为紧邻基线，限制每个产物 raw 增长不超过 2%、gzip/Brotli 不超过 3%，npm 包 packed 不超过 3%、unpacked 不超过 2%、文件数不超过 10%；五个平台产物均拥有直接历史基线。包体测量向上取整到 4 KiB packed 与 64 KiB unpacked，形成不低估真实包体且不受性能报告自包含压缩循环影响的确定性上界。绝对上限或相对上限任一失败都会阻断发布。": "Número de archivos empaquetados, desempaquetados y devueltos. 1.0.0 utiliza los resultados de medición reales de la versión sellada 0.9.0 como base inmediata, limitando el crecimiento bruto de cada producto a no más del 2%, gzip/Brotli a no más del 3%, el paquete npm empaquetado a no más del 3%, desempaquetado a no más del 2% y el número de archivos a no más del 10%; Los cinco productos de plataforma tienen líneas de base históricas directas. Las mediciones del volumen de inclusión se redondean a 4 KiB empaquetado y 64 KiB desempaquetado, formando un límite superior determinista que no subestima el verdadero volumen de inclusión y no se ve afectado por el ciclo de compactación autónomo del informe de desempeño. El fallo del límite absoluto o del límite relativo bloqueará la liberación.",
  "返回对象允许调用的全部成员。": "Devuelve todos los miembros del objeto a los que se les permite llamar.",
  "返回上层对象或列表": "Regresar al objeto o lista de nivel superior",
  "返回首页": "Regresar a la página de inicio",
