  "分栏认证": "Certificación de columna",
  "分栏认证在 704px 以下收敛为单列；卡片在 384px 以下重排 QR、规则与恢复码；底部操作尊重 Safe Area。": "La autenticación de columnas converge en una sola columna por debajo de 704 px; las tarjetas se reorganizan con QR, reglas y códigos de recuperación por debajo de 384 px; Las operaciones de fondo respetan el Área Segura.",
