  "服务器错误、请求编号和重试": "Errores del servidor, números de solicitud y reintentos",
  "浮层、Dialog、Toast 等稳定堆叠顺序": "Secuencia de apilamiento estable de capa flotante, Dialog, Toast, etc.",
  "浮层支持 top / bottom / start / end 与 start / center / end 对齐，空间不足时自动翻转并限制在视口内；RTL 会交换逻辑方向。": "La ​​capa flotante admite la alineación superior/inferior/inicio/final y de inicio/centro/final. Cuando no haya suficiente espacio, se volteará automáticamente y se limitará a la ventana gráfica; RTL intercambiará direcciones lógicas.",
  "浮动动作按钮": "Botón de acción flotante",
  "符号": "Símbolo",
  "负责人": "Persona a cargo",
  "附加配置属性": "Propiedades de configuración adicionales",
  "复用运行时": "Reutilizar tiempo de ejecución",
  "复用桌面菜单项；在线状态、窗口入口与退出": "Reutilizar elementos del menú del escritorio; estado en línea, entrada y salida de ventana",
  "复杂但高复用的页面已经组合为配方。AI 应先选配方，再用组件和工具类做有限调整。": "Se han combinado páginas complejas pero altamente reutilizables en recetas. La IA debe elegir primero las recetas y luego hacer ajustes limitados utilizando componentes y clases de herramientas.",
  "复杂非连续布局": "Diseño complejo no contiguo",
  "复杂任务": "Tareas complejas",
  "复杂业务配方": "Recetas comerciales complejas",
  "复制": "Copiar",
  "复制安装命令": "Copiar comando de instalación",
  "覆盖": "Anulación",
  "覆盖 RTL、容器查询、固定区、Dock、Split View、移动安全区与全屏工作区。既有": "Cubre RTL, consulta de contenedor, área fija, muelle, vista dividida, área segura móvil y espacio de trabajo de pantalla completa. existente",
  "覆盖窗口、工作区、标签、命令、快捷键、文件、托盘、更新、通知和恢复状态。": "Cubre ventanas, espacios de trabajo, pestañas, comandos, accesos directos, archivos, bandejas, actualizaciones, notificaciones y estado de restauración.",
  "覆盖单个列": "Sobrescribiendo una sola columna",
  "覆盖对话、Composer、Prompt、Thinking、工具批准、Agent、Artifact、生成、上下文、费用、权限、安全、语音和反馈。": "Cubre diálogo, compositor, mensaje, pensamiento, aprobación de herramienta, agente, artefacto, compilación, contexto, cargos, permisos, seguridad, voz y comentarios.",
  "覆盖规则：": "Reglas de anulación:",
  "覆盖基础原子、通用组件、高密度后台、移动端、内容商业化、AI 工作区与桌面 WebView。默认足够克制，组合能力足够宽。": "Cubre átomos básicos, componentes comunes, backend de alta densidad, terminal móvil, comercialización de contenido, espacio de trabajo de IA y WebView de escritorio. El valor predeterminado es lo suficientemente restringido y la capacidad de combinación es lo suficientemente amplia.",
  "覆盖目录、SKU、购物车、结算、履约、支付、订单、订阅、账单、退款和税费。": "Cubre catálogo, SKU, carrito, pago, cumplimiento, pagos, pedidos, suscripciones, facturación, reembolsos e impuestos.",
  "覆盖内在响应、RTL、容器查询、Bento、Masonry、滚动吸附、安全区和打印结构。已有": "Cubre respuestas intrínsecas, RTL, consultas de contenedores, Bento, Masonry, ajuste de desplazamiento, áreas seguras y estructuras de impresión. Ya",
  "覆盖全部根类、业务字段组、动态增删、条件显示、容器响应、RTL 与打印。": "Cubre todas las clases raíz, grupos de campos comerciales, adiciones y eliminaciones dinámicas, visualización condicional, respuesta de contenedor, RTL e impresión.",
  "覆盖全部模式并可直接测试 OTP、密码强度、倒计时、账号/租户选择和身份菜单。": "Cubre todos los modos y permite la prueba directa de OTP, seguridad de la contraseña, cuenta regresiva, selección de cuenta/inquilino y menú de identidad.",
  "覆盖全局、层级、选择、菜单、页内、流程、移动与桌面导航，并可直接测试键盘和右键交互。": "Cubre la navegación global, jerárquica, de selección, de menú, en página, de procesos, móvil y de escritorio, y puede probar directamente las interacciones del teclado y del clic derecho.",
  "覆盖上传、文件浏览、媒体、图片、文档、音视频、四类编辑器、协作、版本和存储。": "Cubre carga, exploración de archivos, medios, imágenes, documentos, audio y video, cuatro tipos de editores, colaboración, versiones y almacenamiento.",
  "覆盖所有根类、RTL/移动响应、Tooltip、Popover、FAQ 与两步 Tour。": "Cubre todas las clases raíz, RTL/Responsivo para dispositivos móviles, información sobre herramientas, ventana emergente, preguntas frecuentes y recorrido en dos pasos.",
  "覆盖所有页头、公共栏、Loading、Empty、Error、403、404、500、Offline、Maintenance、Container Query 和 Back to Top。": "Cubre todos los encabezados, campos comunes, Cargando, Vacío, Error, 403, 404, 500, Sin conexión, Mantenimiento, Consulta de contenedor y Volver al principio.",
  "概览": "Descripción general",
  "高复用复杂结构作为组件或配方存在，不要求 AI 每次临时组合。": "Las estructuras complejas altamente reutilizables existen como componentes o recetas y no requieren que la IA se combine temporalmente cada vez.",
  "高密度工作区无需重新拼装": "No es necesario volver a ensamblar para espacios de trabajo de alta densidad",
  "高密度数据、表格、过滤器和多栏应用。": "Datos, tablas, filtros y aplicaciones de varias columnas de alta densidad.",
  "高频页面不必重新拼装": "No es necesario volver a ensamblar las páginas de alta frecuencia",
