  "恢复文档、恢复会话、安全启动、放弃恢复": "Restaurar documento, restaurar sesión, inicio seguro, abandonar restauración",
  "会根据内容最小宽度自动从双栏切换为纵向，不要求 AI 推测应使用哪个视口断点。": "Cambia automáticamente de columna doble a vertical según el ancho mínimo del contenido, sin necesidad de que la IA adivine qué punto de interrupción de la ventana gráfica se debe usar.",
  "会核对真实 npm 包白名单、每个导出目标、类型文件、开发目录泄漏与 Publint；": "Verificará la lista blanca de paquetes npm reales, cada destino de exportación, tipo de archivo, fugas del directorio de desarrollo y Publint;",
  "会话过期": "La sesión expiró",
  "会记录当前正式输出、重新执行完整构建，再比较 CSS、JavaScript、Source Map、元数据与": "registrará el resultado oficial actual, volverá a ejecutar la compilación completa y luego comparará CSS, JavaScript, mapa fuente, metadatos y",
  "会随书写方向变化。需要固定视觉左/右的特殊画布应自行明确方向，不要破坏公共逻辑语义。": "cambia con la dirección de escritura. Los lienzos especiales que requieren una visión fija izquierda/derecha deben aclarar la dirección por sí solos sin romper la semántica lógica común.",
  "会先销毁再按当前配置初始化节点子树；作用域": "El subárbol de nodos se destruirá primero y luego se inicializará según la configuración actual; alcance",
