  "接受组件名、AngularJS 指令名或 ESM 导出名，并由 506 项联合类型约束；未知名称会立即抛错。同一 AngularJS 实例、模块名和等价选项重复安装是幂等的，不同组件子集、依赖或初始化选项使用同名模块时会明确报错，防止静默得到半注册模块。": "Acepta un nombre de componente, un nombre de directiva AngularJS o un nombre de exportación de ESM, restringido por 506 tipos de unión; Los nombres desconocidos arrojarán inmediatamente un error. Las instalaciones repetidas de la misma instancia de AngularJS, nombre de módulo y opciones equivalentes son idempotentes. Cuando diferentes subconjuntos de componentes, dependencias u opciones de inicialización utilizan módulos con el mismo nombre, se informará explícitamente un error para evitar la obtención silenciosa de módulos semirregistrados.",
