  "可关闭组件自动初始化， 方便由页面级运行时统一接管。显式传入的行为 data attribute 优先于生成默认值。": "La inicialización automática de componentes se puede desactivar para facilitar la toma de control unificada por parte del tiempo de ejecución a nivel de página. El comportamiento de pasar explícitamente un atributo de datos tiene prioridad sobre generar un valor predeterminado.",
  "可滚动区域应可被键盘聚焦并提供可访问名称；Reduced Motion 会取消原语的平滑滚动。": "Las áreas desplazables deben poder enfocarse con el teclado y proporcionar un nombre accesible; El movimiento reducido suprime el desplazamiento suave de las primitivas.",
