  "可直接测试 App Bar、Bottom Navigation、Swipe Tabs、Swipe Actions、Infinite Load、Action/Filter Sheet 与移动选择器。": "Prueba directa de la barra de aplicaciones, navegación inferior, pestañas de deslizamiento, acciones de deslizamiento, carga infinita, hoja de acción/filtro y selectores móviles.",
  "可直接测试排序、选择、展开、列显隐、搜索、视图切换、移动堆叠表和键盘网格。": "Se pueden probar directamente la clasificación, selección, expansión, visibilidad de columnas, búsqueda, cambio de vista, movimiento de tablas apiladas y cuadrícula de teclado.",
  "可直接测试全选、反选、范围选择、Transfer、Picker、Cascader、Saved Choice 和动态 Builder。": "Seleccionar todo, Selección inversa, Selección de rango, Transferencia, Selector, Cascada, Elección guardada y Generador dinámico se pueden probar directamente.",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包实测为 326,076 B raw、50,128 B gzip、26,375 B Brotli；单个": "Legible directamente mediante IA, generadores de código y herramientas de documentación. La medida real del paquete comprimido completo es 326.064 B raw, 50.126 B gzip, 26.381 B Brotli; soltero",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包实测为 404,104 B raw、59,503 B gzip、29,798 B Brotli；单个": "Legible directamente mediante IA, generadores de código y herramientas de documentación. La medida real del paquete comprimido completo es 404.094 B raw, 59.499 B gzip, 29.785 B Brotli; soltero",
