  "框架提供焦点样式、减少动效、高对比和 Forced Colors 基础，但语义名称与内容顺序仍由页面作者负责。": "El marco proporciona una base para estilos de enfoque, movimiento reducido, alto contraste y colores forzados, pero la denominación semántica y el orden del contenido siguen siendo responsabilidad del autor de la página.",
  "扩展": "Extensión",
  "了解发布状态": "Comprender el estado de la versión",
  "类。": ".",
  "类必须出现在“CSS 全量 API”或“工具类”清单；每个组件、运行时和页面配方还必须出现在各自目录。构建校验会逐文件计算 SHA-256，避免目录落后于源码。": "La clase debe aparecer en la lista CSS Full API o Clases de herramientas; cada componente, tiempo de ejecución y receta de página también deben aparecer en sus respectivos directorios. La verificación de compilación calcula SHA-256 archivo por archivo para evitar que los directorios se queden atrás del código fuente.",
  "类名": "Nombre de clase",
  "类型，并保留默认语义标签、选择器、状态、部件、行为、平台与无障碍元数据。静态 SSR 阶段直接输出完整 HTML，建立交互连接后才挂载 DOM 行为；参数签名改变会刷新挂载，组件释放时会注销监听器。": "escriba y conserve etiquetas semánticas, selectores, estados, widgets, comportamientos, plataforma y metadatos de accesibilidad predeterminados. La fase SSR estática genera directamente HTML completo y solo monta el comportamiento DOM después de establecer una conexión interactiva; Los cambios en las firmas de los parámetros actualizarán el montaje y el oyente cerrará la sesión cuando se lance el componente.",
  "类型、所有者、校验值和版权": "Tipo, propietario, valor del cheque y copyright",
  "类型安全监听 gardener:* 事件": "Escucha con seguridad de tipos para jardinero:* eventos",
