  "逻辑方向属性覆盖 RTL；Reduced Motion 停止同步脉冲；Forced Colors 为当前 Activity/Tab/Command 提供明确轮廓。": "El atributo de dirección lógica anula RTL; El movimiento reducido detiene los pulsos de sincronización; Colores forzados proporciona un esquema claro para la actividad/pestaña/comando actual.",
  "逻辑方向属性支持 RTL；Reduced Motion 关闭位移过渡；Forced Colors 强化选中轮廓；打印自动展平外壳。": "El atributo de dirección lógica admite RTL; El movimiento reducido desactiva las transiciones de desplazamiento; Forced Colors realza los contornos seleccionados; La impresión aplana automáticamente las conchas.",
  "没有": "Ninguno",
