  "没有匹配的组件。": "No hay ningún componente coincidente.",
  "媒体上叠工具、标注、状态；align / justify / margin": "Herramientas de superposición de medios, anotaciones, estado; alinear / justificar / margen",
  "媒体资产工作台与详情栏": "Panel de trabajo de recursos multimedia y barra de detalles",
  "每份自定义构建清单还会为可读 CSS、压缩 CSS、Source Map 和随包复制的 Tauri/Electron 适配器生成 SHA-256 与标准 SRI。接收方无需依赖构建机器，即可逐文件验证交付内容是否完整且未被替换。": "Cada manifiesto de compilación personalizado también genera SHA-256 y SRI estándar para CSS legible, CSS comprimido, mapa fuente y el adaptador Tauri/Electron copiado con el paquete. El destinatario puede verificar archivo por archivo que la entrega está completa y no ha sido reemplazada, sin depender de la máquina de construcción.",
  "每个 CSS 组件都有对应的": "Cada componente CSS tiene su correspondiente",
  "每个公共组件都能解析到完整所属包，并明确列出连带包含项。": "Cada componente público se resuelve en el paquete completo al que pertenece, con inclusiones explícitas enumeradas.",
  "每个目录同时生成可读 CSS、正式": "Generación simultánea de CSS legible por directorio, formal",
