  "默认": "Predeterminado",
  "默认 125 个真实浏览器用例": "Predeterminado 125 casos de uso reales del navegador",
  "默认、info、success、warning、danger；紧凑技巧": "Predeterminado, información, éxito, advertencia, peligro; habilidades compactas",
  "默认白色 Surface 与 4px 小圆角；组件只使用主题 Token，可在 42 套主色和所有正交主题轴中复用。": "Superficie blanca predeterminada con pequeñas esquinas redondeadas de 4px; el componente solo utiliza tokens temáticos, que se pueden reutilizar en 42 conjuntos de colores principales y todos los ejes temáticos ortogonales.",
  "默认白色 Surface、1px 边框和 4px 小圆角；阴影仅用于命令面板、窗口切换器和菜单等真实浮层。": "Superficie blanca predeterminada, borde de 1 px y esquinas redondeadas pequeñas de 4 px; Las sombras solo se usan para superposiciones reales, como paneles de comando, conmutadores de ventanas y menús.",
  "默认白色 Surface、1px 边框与 4px 小圆角；大圆角和强阴影不是移动端默认。": "Superficie blanca predeterminada, borde de 1 px y esquinas redondeadas pequeñas de 4 px; Las esquinas grandes y redondeadas y las sombras fuertes no son lo predeterminado para los dispositivos móviles.",
  "默认导入。Gardener 包本身不会读取全局 AngularJS，根入口可安全用于 SSR 工具链分析。": "Importado por defecto. El paquete Gardener en sí no lee AngularJS global y la entrada raíz es segura para el análisis de la cadena de herramientas SSR.",
  "默认风格适合个人、企业、后台和内容站，不预设强烈品牌人格。": "El estilo predeterminado es adecuado para individuos, empresas, backends y estaciones de contenido, y no preestablece una personalidad de marca fuerte.",
  "默认视觉：": "Visual predeterminado:",
  "默认小圆角，可显式扩展": "Esquinas redondeadas pequeñas predeterminadas, se pueden extender explícitamente",
  "默认与整行": "Predeterminado versus línea completa",
  "默认执行 125 个真实浏览器用例和 24 个 HTML 结构用例；完整配置覆盖桌面三引擎、Android / iPhone 设备画像和 WCAG 自动检查。": "Ejecuta 125 casos de uso de navegador real y 24 casos de uso de estructura HTML de forma predeterminada; La configuración completa cubre tres motores de escritorio, retratos de dispositivos Android/iPhone y comprobaciones automáticas WCAG.",
