  "使用 704px 容器折叠；文件浏览、媒体详情、图片编辑器、文档缩略图、Markdown 双栏和版本对比均有移动布局。": "Utilice el colapso del contenedor de 704 px; El explorador de archivos, los detalles multimedia, el editor de imágenes, las miniaturas de documentos, las columnas dobles de Markdown y la comparación de versiones tienen diseños móviles.",
  "使用 Ajv 2020-12 执行 48 个标准验证用例，覆盖十份发布/配置文档、未知根字段、十类未知嵌套字段、十类缺失嵌套必填字段、跨 Schema 引用、JavaScript 标识符、SHA-256 格式、基线回归状态和旧组件 Schema 兼容别名；": "Se ejecutaron 48 casos de uso de validación estándar utilizando Ajv 2020-12, que cubren diez documentos de versión/configuración, campos raíz desconocidos, diez tipos de campos anidados desconocidos, diez tipos de campos obligatorios anidados faltantes, referencias entre esquemas, identificadores de JavaScript, formatos SHA-256, estado de regresión de referencia y alias compatibles con esquemas de componentes heredados;",
  "使用 gzip level 9 与 Brotli quality 11，对全部 42 个正式压缩产物同时计算 raw、gzip 和 Brotli，并检查全量 CSS、Runtime 的压缩比例，以及": "Utilizando gzip nivel 9 y Brotli calidad 11, calcule simultáneamente raw, gzip y Brotli para los 42 productos de compresión oficiales y verifique la relación de compresión de CSS completo, tiempo de ejecución y",
  "使用 Node.js 内置测试运行器和 Happy DOM，对公共清单中的全部 66 种行为逐项双向比对真实实例成员，并验证初始化、幂等性、销毁和重新初始化；同时覆盖 MutationObserver 的动态节点、动态属性、子树移除、作用域销毁、多行为共存、全局销毁和初始化事件冒泡。": "Utilice el ejecutor de pruebas integrado de Node.js y Happy DOM para comparar bidireccionalmente miembros de instancias reales para los 66 comportamientos en la lista pública y verificar la inicialización, idempotencia, destrucción y reinicialización; mientras cubre los nodos dinámicos de MutationObserver, los atributos dinámicos, la eliminación de subárboles, la destrucción del alcance, la coexistencia de múltiples comportamientos, la destrucción global y la propagación de eventos de inicialización.",
  "使用 TypeScript 严格模式编译真实消费者，覆盖默认及命名导出、行为工厂、Toast、实例查询和两类桌面桥接。": "Compile consumidores reales utilizando el modo estricto de TypeScript, que cubre exportaciones predeterminadas y con nombre, fábricas de comportamiento, notificaciones del sistema, consultas de instancias y dos tipos de puentes de escritorio.",
