  "视口响应 · 容器响应 · 逻辑方向 · 打印展平 · 桌面工作台": "Capacidad de respuesta de la ventana gráfica · Capacidad de respuesta del contenedor · Dirección lógica · Acoplamiento de impresión · Mesa de trabajo de escritorio",
  "视口小于 768px 时，多栏、Master / Detail 和检查器布局按语义顺序纵向排列；Dock 默认只保留主区，可用": "Cuando la ventana gráfica tiene menos de 768 píxeles, los diseños de varias columnas, Maestro/Detalle e Inspector se organizan verticalmente en orden semántico; el Dock solo conserva el área principal de forma predeterminada y está disponible",
