  "试用": "Prueba",
  "是 Gardener CSS 1.0.0 的官方 AngularJS 1.x 遗留系统适配层，当前版本为": "es la capa oficial de adaptación del sistema heredado de AngularJS 1.x para Gardener CSS 1.0.0, la versión actual es",
  "是 Gardener CSS 1.0.0 的官方 Razor Class Library，当前版本为": "es la biblioteca de clases oficial de Razor para Gardener CSS 1.0.0, la versión actual es",
  "是 Gardener CSS 1.0.0 的官方 React 适配层，当前版本为": "es la capa de adaptación oficial de React de Gardener CSS 1.0.0, la versión actual es",
  "是 Gardener CSS 1.0.0 的官方 Vue 3 适配层，当前版本为": "es la capa de adaptación oficial de Vue 3 de Gardener CSS 1.0.0, la versión actual es",
  "是给生成器使用 Gardener 的约束。前者提供界面组件，后者规定选能力、配方、组件和工具类的顺序。": "es una restricción para el uso de Gardener en generadores. El primero proporciona componentes de interfaz y el segundo especifica el orden en el que se seleccionan capacidades, recetas, componentes y clases de herramientas.",
  "是公共命名与程序接口的规范清单，完整登记 CSS 层、包入口、主题属性、JavaScript 导出、行为、事件、桌面适配器和兼容字段。": "es una lista canónica de interfaces de programación y nombres públicos, que registra completamente capas CSS, entradas de paquetes, propiedades de temas, exportaciones de JavaScript, comportamientos, eventos, adaptadores de escritorio y campos de compatibilidad.",
  "是五个公共区域；": "son cinco áreas comunes;",
  "是预压缩单文件入口。SSR 导入不访问浏览器全局对象，行为只在组件挂载后初始化，因此可用于服务端渲染与 Hydration。": "es una entrada de archivo único precomprimido. La importación SSR no accede a los objetos globales del navegador y el comportamiento solo se inicializa después de montar el componente, por lo que se puede utilizar para la renderización e hidratación del lado del servidor.",
  "适合 WebView": "Adecuado para WebView",
