  "收录完整 42 个颜色主题，默认保持白底 Light 与小圆角 small。 5 个作用域服务为": "Contiene 42 temas de color, con el fondo blanco predeterminado Claro y pequeñas esquinas redondeadas pequeñas. Los 5 servicios de alcance son",
