  "手势只增强效率：Pull Refresh 有刷新按钮路径，Infinite Load 有“加载更多”，Swipe Actions 有 Toggle，Wheel Picker 支持键盘。": "Los gestos solo mejoran la eficiencia: Pull Refresh tiene una ruta de botón de actualización, Infinite Load tiene \"cargar más\", Swipe Actions tiene Toggle y Wheel Picker tiene soporte para teclado.",
