  "输出前校验端点、键盘、焦点、状态、RTL、打印和高对比环境。": "Verifique los terminales, el teclado, el enfoque, el estado, RTL, la impresión y los entornos de alto contraste antes de la salida.",
  "输入发送到 +86 138****6608 的验证码": "Ingrese el código de verificación enviado al +86 138****6608",
  "输入类名、完整选择器、CSS 属性、值或响应条件。为避免一次渲染 11,498 项，至少输入两个字符后分批显示，每次 100 项；输入": "Ingrese un nombre de clase, selector completo, propiedad CSS, valor o condición de respuesta. Para evitar mostrar 11.498 elementos a la vez, ingrese al menos dos caracteres antes de mostrarlos en lotes de 100 elementos a la vez; entrar",
