  "属性、样式、审计、上下文信息": "Propiedades, estilos, auditoría, información contextual",
  "属性的真实源码命中，将 506 个组件解析到一个或多个完整所属包，而不是截取单个选择器，因此伪类、状态、动画、子部件、容器查询和依赖规则不会丢失。": "Accesos de código fuente real para propiedades, resolviendo 506 componentes en uno o más paquetes completos pertenecientes en lugar de truncar selectores individuales, para que no se pierdan pseudoclases, estados, animaciones, subpartes, consultas de contenedores y reglas de dependencia.",
