  "缩略图网格与媒体多选": "Cuadrícula de miniaturas y selección múltiple de medios",
  "所有 32 模式均进入组件 Manifest 和动态组件目录；CSS 源码完整 API 也会列出模块、选择器、变量和状态。": "Los 32 modos van a manifiestos de componentes y directorios de componentes dinámicos; La API completa de fuente CSS también enumera módulos, selectores, variables y estado.",
  "所有结构采用逻辑方向属性并支持 RTL；Forced Colors 提供选择轮廓；打印隐藏数据操作，展开详情和层级行，并移除滚动裁切。": "Todas las estructuras adoptan atributos de dirección lógica y admiten RTL; Colores forzados proporciona esquemas de selección; imprima operaciones de datos ocultos, expanda filas de detalles y jerarquía y elimine el recorte de desplazamiento.",
  "所有开始、结束和操作对齐使用逻辑方向；Floating Action Bar、Back to Top 同时读取设备安全区。": "Todas las alineaciones de inicio, fin y acción utilizan dirección lógica; La barra de acción flotante, Volver al principio también lee el área segura del dispositivo.",
  "所有模式覆盖键盘、RTL、Reduced Motion、Forced Colors 与打印；移动结算尊重 Safe Area，打印隐藏购买动作并保留订单、发票和税费信息。": "Todos los modos cubren teclado, RTL, movimiento reducido, colores forzados e impresión; la facturación móvil respeta el Área Segura, la impresión oculta las acciones de compra y conserva la información del pedido, la factura y los impuestos.",
  "所有模式使用白色 Surface、1px 边框和4px小圆角；在 960/704/512px 容器宽度下折叠 Artifact、Sidebar 与双列模式，并覆盖 RTL、Forced Colors 和打印。": "Utilice Superficie blanca, borde de 1 px y esquinas redondeadas pequeñas de 4 px en todos los modos; colapsar los modos Artefacto, Barra lateral y Columna dual en un ancho de contenedor de 960/704/512 px y anular RTL, Colores forzados e Imprimir.",
  "所有模式使用逻辑方向并覆盖 RTL、Reduced Motion、Forced Colors 和打印；打印隐藏上传与编辑动作，展平滚动区并保留正文和修订信息。": "Todos los modos utilizan dirección lógica y cubren RTL, movimiento reducido, colores forzados e impresión; Imprimir oculta las acciones de carga y edición, aplana el área de desplazamiento y conserva el texto y la información de revisión.",
  "所有水平语义使用 inline/start/end；Media Object、Bleed、Imposter、Overlay、Reel 和 Scroll Snap 支持 RTL。": "Toda la semántica horizontal utiliza inline/start/end; Objeto multimedia, sangrado, impostor, superposición, carrete y ajuste de desplazamiento admiten RTL.",
  "所有图片有符合目的的": "Todas las imágenes son aptas para su propósito.",
  "所有样式覆盖 RTL、Reduced Motion、Forced Colors 与打印。打印隐藏密码、Provider、倒计时和敏感操作，只保留必要的安全审计信息。": "Todos los estilos cubren RTL, movimiento reducido, colores forzados e impresión. Imprima contraseñas ocultas, proveedores, cuentas regresivas y operaciones confidenciales, conservando solo la información de auditoría de seguridad necesaria.",
  "所有原生 attributes、DOM 事件和 slots 均透传。组件模板 Ref 统一公开": "Se pasan todos los atributos nativos, eventos DOM y ranuras. Plantilla de componente Ref divulgación unificada",
  "所有组合使用逻辑方向属性；Input Group、Money、Unit、字段动作和 Sticky Actions 在 RTL 下保持正确首尾关系。": "Todas las combinaciones utilizan atributos de dirección lógica; El grupo de entrada, el dinero, la unidad, las acciones de campo y las acciones fijas mantienen una relación directa correcta en RTL.",
  "锁屏": "Pantalla de bloqueo",
  "套餐、版本和能力横向比较": "Comparación horizontal de paquetes, versiones y capacidades",
  "提供 640px 容器折叠；移动端 Picker Panel 自动成为底部面板，Batch Toolbar 避让安全区。": "Proporciona un colapso del contenedor de 640 px; el panel selector móvil se convierte automáticamente en el panel inferior y la barra de herramientas por lotes evita el área segura.",
  "提供 Unicode 搜索、网格/列表切换、单项选择、方向键、Home、End、Enter 和 Space，并发布选择事件。": "Proporciona búsqueda Unicode, cambio de cuadrícula/lista, selección única, teclas de flecha, Inicio, Fin, Intro y Espacio, y publica eventos de selección.",
  "提供传统 12 栅格。两者都使用原生 CSS Grid、逻辑方向和统一断点，不依赖负边距。": "Proporciona 12 cuadrículas tradicionales. Ambos utilizan CSS Grid nativo, dirección lógica y puntos de interrupción unificados, y no dependen de márgenes negativos.",
  "提供每个页面的端、部件、运行时和用途；": "Proporciona la terminal, los widgets, el tiempo de ejecución y el propósito de cada página;",
  "提供适合编辑器、AI 工具和超级 CMS 的固定视口布局。通过": "Proporciona un diseño de ventana gráfica fija adecuado para editores, herramientas de inteligencia artificial y super CMS. Pase",
  "提供稳定初始高度，": "Proporciona altitud inicial estable,",
