  "同一套 CSS，也有完整的 React 组件模型": "El mismo conjunto de CSS también tiene un modelo de componente React completo",
  "同一套语言，覆盖所有端": "El mismo idioma cubre todos los terminales",
  "同一整页契约可切换企业、个人、医疗、金融或公共服务主题。": "El mismo contrato de página completa puede cambiar temas comerciales, personales, médicos, financieros o de servicios públicos.",
  "统一": "Unificación",
  "统一垂直节奏；default、bordered": "Ritmo vertical unificado; predeterminado, bordeado",
  "统一单选/多选、Unicode 搜索、Chip 删除、隐藏字段输出、方向键、Home、End、Enter、Space、Escape 和点击外部关闭。": "Selección única/múltiple unificada, búsqueda Unicode, eliminación de chip, salida de campo oculto, teclas de flecha, Inicio, Fin, Intro, Espacio, Escape y haga clic afuera para cerrar.",
  "统一的": "unificado",
  "统一工具命令、Ctrl/Command 快捷键、字符与词数；富文本、Markdown、代码和区块编辑器共用协议。": "Unificar comandos de herramientas, atajos de Ctrl/Comando, recuento de caracteres y palabras; Protocolos comunes para texto enriquecido, Markdown, editores de código y bloques.",
  "统一命名": "Nomenclatura unificada",
