  "先建立租户与身份边界，再组织内容工作流、Dashboard 和门户页面。": "Establezca límites de identidad y inquilinos antes de organizar flujos de trabajo de contenido, paneles y páginas del portal.",
  "先判断导航范围（全局、局部、层级或页内），再判断方向和终端；Tabs 只切换同一上下文内的视图，Breadcrumb 只表达位置，Pagination 只表达结果集翻页，不应互相替代。": "Primero determine el alcance de navegación (global, local, jerárquica o intrapágina), y luego determine la dirección y terminal; Las pestañas solo cambian las vistas dentro del mismo contexto, Breadcrumb solo expresa la posición y Paginación solo expresa el cambio de página del conjunto de resultados y no deben reemplazarse entre sí.",
  "先判断数据形态，再判断操作强度。少量静态属性用 Description List 或 Key Value；多记录用 List 或 Table；单元格需要键盘移动和编辑时才使用 Data Grid；层级数据使用 Tree 或 Tree Table；趋势和比较先提供可读数值，再增加图形。": "Determine primero el formulario de datos y luego la intensidad de la operación. Utilice la lista de descripción o el valor clave para una pequeña cantidad de atributos estáticos; use Lista o Tabla para múltiples registros; use Data Grid solo cuando las celdas requieran movimiento y edición del teclado; utilice Árbol o Tabla de árbol para datos jerárquicos; Las tendencias y comparaciones proporcionan primero valores legibles y luego agregan gráficos.",
