  "颜色主题与中性色、字体、形状、密度、层次、动效、平台和操作系统正交组合。这里始终保持白色浅色界面，只切换品牌主色。": "Los temas de color se combinan ortogonalmente con neutros, fuentes, formas, densidades, capas, animaciones, plataformas y sistemas operativos. La interfaz de blanco y luz siempre se mantiene aquí y solo se cambia el color de la marca principal.",
  "颜色主题只负责品牌主色；显示模式与其他主题轴相互独立。本站固定使用 Light，以保持白色文档体验，但框架同时提供 Dark、System 与 High Contrast。": "El tema de color solo es responsable del color principal de la marca; el modo de visualización es independiente de otros ejes temáticos. Este sitio utiliza Light para mantener una experiencia de documento en blanco, pero el marco también proporciona Dark, System y High Contrast.",
