  "页面不能只实现正常数据态。至少要明确 Loading、Empty、Error；面向路由和完整应用时还应准备 403、404、500、Offline 和 Maintenance。Gardener 为这些状态提供相同的内容、视觉、详情、操作和帮助部件。": "La página no puede implementar solo el estado de datos normal. Al menos deben quedar claros Cargando, Vacío y Error; para enrutar y completar aplicaciones, también se deben preparar 403, 404, 500, fuera de línea y mantenimiento. Gardener proporciona el mismo contenido, imágenes, detalles, acciones y widgets de ayuda para estos estados.",
