  "页面结构、主题 Token 与交互语义保持一致，各端只增加必要的密度、窗口和安全区适配。": "La estructura de la página, el token del tema y la semántica de interacción son consistentes y solo se agregan las adaptaciones necesarias de densidad, ventana y zona segura en cada extremo.",
