  "页面状态的 visual、code、title、description、details、actions、help 部件可以按需要省略，但标题和可恢复入口不应同时缺失。": "Los componentes visuales, código, título, descripción, detalles, acciones y ayuda del estado de la página se pueden omitir según sea necesario, pero el título y la entrada restaurable no deben faltar al mismo tiempo.",
