  "营销、个人和内容页使用自然文档滚动；Dashboard 与工作台允许高密度多栏；医疗、金融和政务只是 UI 契约，不替代法规、身份验证、隐私、审计和后端业务规则。": "Las páginas de marketing, personales y de contenido utilizan el desplazamiento natural de los documentos; El tablero y el banco de trabajo permiten múltiples columnas de alta densidad; Atención médica, finanzas y gobierno son contratos de UI únicamente y no reemplazan las regulaciones, la autenticación, la privacidad, la auditoría ni las reglas comerciales de backend.",
