  "用于真实验证 24 / 12、RTL、Container Query 与打印结构。构建检查会逐项验证所有类，而不是只检查几个示例。": "Para verificación real 24 / 12, RTL, Consulta de Contenedor y estructura de impresión. Las comprobaciones de compilación verifican todas las clases una por una en lugar de simplemente verificar algunos ejemplos.",
  "用于直接读取上下文。默认仍是白色 Light 与小圆角，不会自动启用深色主题。": "para leer el contexto directamente. El valor predeterminado sigue siendo Luz blanca con pequeñas esquinas redondeadas y el tema oscuro no se habilitará automáticamente.",
