  "与 Node.js": "con Node.js",
  "与安全 preload，只暴露 Minimize、Maximize/Restore、Close 等白名单方法；不要开启 Node Integration，也不要把任意 IPC 通道暴露给页面。": "Con la carga previa de seguridad, solo se exponen métodos de lista blanca como Minimizar, Maximizar/Restaurar y Cerrar; no habilite la integración de nodos y no exponga ningún canal de IPC a la página.",
