  "原生 input 后备；发出": "Reserva de entrada nativa; emitido",
  "原生 input、textarea 和 select 的模型语义仍由 AngularJS 自己管理，适配层不会覆盖": "La semántica del modelo de entrada nativa, área de texto y selección aún es administrada por AngularJS y no estará cubierta por la capa de adaptación.",
  "原生 input/change 自动去重": "Deduplicación automática de entrada/cambio nativo",
  "原生标题栏、窗口按钮、菜单和活动栏只是起点；文档标签、可调分栏、Dock、检查器、命令面板、文件选择、托盘、多窗口、后台任务、更新、权限与崩溃恢复均已有稳定组合，可直接落地 Tauri 与 Electron。": "Las barras de título, botones de ventana, menús y barras de actividad nativos son solo el punto de partida; Las etiquetas de los documentos, las columnas ajustables, el Dock, el inspector, el panel de comandos, la selección de archivos, la bandeja, las ventanas múltiples, las tareas en segundo plano, las actualizaciones, los permisos y la recuperación ante fallos se han combinado de manera estable y se pueden implementar directamente en Tauri y Electron.",
  "原生表单和自定义 Gardener 事件均支持": "Se admiten eventos de Gardener personalizados y de forma nativa",
  "原生权限请求、网络状态、数据加载、支付、认证和媒体缩放由业务或宿主实现；Gardener 提供稳定视觉、状态、事件与无障碍接口，不伪造结果。": "Las solicitudes de permisos nativos, el estado de la red, la carga de datos, el pago, la autenticación y el escalado de medios son implementados por la empresa o el host; Gardener proporciona visión estable, estado, eventos e interfaces accesibles sin forjar resultados.",
