  "阅读文档": "Leer documentación",
  "允许后续 1.x 新增，禁止无迁移路径的删除；在 1.0.0 稳定切点还会反向检查已有入口是否漏记。废弃入口至少保留两个次版本，并只能在新的主版本移除。其闭合结构由": "Permitir adiciones posteriores a 1.x y prohibir eliminaciones sin rutas de migración; en el punto de corte estable 1.0.0, las entradas existentes también se verificarán a la inversa para ver si faltan. Las entradas obsoletas permanecen en al menos dos versiones menores y solo se pueden eliminar en una nueva versión principal. Su estructura cerrada consta de",
  "允许写入页面模板？": "¿Permitir escribir en la plantilla de página?",
  "允许一次": "Permitido una vez",
  "运行环境": "Entorno operativo",
  "运行时": "Tiempo de ejecución",
  "运行时，根据滚动位置显示，点击后平滑返回顶部；Reduced Motion 环境自动使用即时滚动。": "En tiempo de ejecución, la visualización se basa en la posición de desplazamiento y regresa suavemente a la parte superior después de hacer clic; el entorno de movimiento reducido utiliza automáticamente el desplazamiento instantáneo.",
  "运行时、可访问性与环境规则": "Reglas de tiempo de ejecución, accesibilidad y entorno",
  "运行时测试门禁（0.4.0 起）": "Prueba de control de acceso en tiempo de ejecución (desde 0.4.0)",
  "运行时框架无关，通过": "Marco de tiempo de ejecución independiente, aprobado",
  "运行时事件": "Eventos de tiempo de ejecución",
  "运行时维护状态": "Estado de mantenimiento en tiempo de ejecución",
  "运行时行为新增或改名时，公共 API、示例/补充夹具和逐行为测试必须同步，否则测试会因缺少夹具、实例或成员而失败。": "Cuando se agrega o cambia el nombre de un comportamiento en tiempo de ejecución, la API pública, los dispositivos de muestra/suplementarios y las pruebas por comportamiento deben sincronizarse; de lo contrario, las pruebas fallarán debido a la falta de dispositivos, instancias o miembros.",
  "运行时与环境规则": "Reglas de entorno y tiempo de ejecución",
  "运行中": "En ejecución",
  "在 200% 缩放、RTL、Reduced Motion、Forced Colors 下仍可操作。": "Aún funciona con escala del 200 %, RTL, movimiento reducido y colores forzados.",
  "在 704px 折叠详情/结算双栏，在 480px 重排行项目与选择卡；视口查询作为没有容器上下文时的兜底。": "Contraer columnas duales de detalles/pago a 704 px, reordenar líneas de pedido y seleccionar tarjetas a 480 px; consulta de ventana gráfica como alternativa cuando no hay contexto de contenedor.",
