  "展开任一模块可查看该文件公开的类、Token、状态、数据属性和关键帧。生成型工具模块链接到独立的 11,498 项清单。": "Expanda cualquier módulo para ver las clases, tokens, estados, atributos de datos y fotogramas clave expuestos por el archivo. El módulo de herramientas generativas se vincula a un inventario separado de 11,498 artículos.",
