  "这是我": "Este soy yo",
  "正式 CSS 与 JavaScript 使用 esbuild 做语法级压缩，不使用正则替换；主压缩入口和每次自定义构建生成可追溯的外部 Source Map。压缩 CSS 使用不随版本变化的稳定 MIT banner，避免纯版本文本扰动 Brotli 基线，未压缩 CSS 与 Runtime 仍提供精确版本。": "CSS y JavaScript formales utilizan esbuild para la compresión a nivel de sintaxis sin utilizar reemplazos regulares; la entrada de compresión principal y cada compilación personalizada generan un mapa fuente externo rastreable. CSS comprimido utiliza un banner MIT estable que no cambia con las versiones para evitar que el texto de la versión pura altere la línea base de Brotli. El CSS sin comprimir y el tiempo de ejecución aún proporcionan versiones precisas.",
