  "字段、分区、水平与行内布局、搜索/密码/计数、选择组、验证、姓名/地址/金额、条件与可重复项、审核和提交动作都已组合好。AI 只需选择业务意图，不必反复组织表单 CSS。": "Se combinan campos, particiones, diseño horizontal y en línea, búsqueda/contraseña/recuento, grupos seleccionados, validación, nombre/dirección/monto, condiciones y repetibles, revisión y envío de acciones. La IA solo necesita seleccionar la intención comercial y no tiene que organizar el formulario CSS una y otra vez.",
