  "自动初始化。MutationObserver 同时处理新增节点和后加行为属性，适合 SPA、CMS 画布和 AI 流式生成 DOM。": "Inicialización automática. MutationObserver maneja nuevos nodos y atributos de comportamiento agregados al mismo tiempo, y es adecuado para SPA, lienzo CMS y transmisión de IA para generar DOM.",
  "自动初始化与动态 DOM 观察": "Inicialización automática y observación DOM dinámica",
