  "自动化": "Automatización",
  "自动生成，覆盖每个源码模块、语义类、原始选择器、Token、自定义状态钩子、数据属性和关键帧；工具类使用下一节的专用完整清单。它是源码级目录，不是精选示例。": "Generado automáticamente, que cubre cada módulo de código fuente, clase semántica, selector primitivo, token, enlace de estado personalizado, atributo de datos y fotograma clave; para clases de herramientas utilice la lista completa dedicada en la siguiente sección. Es un directorio de nivel fuente, no un ejemplo destacado.",
