  "作为兼容别名保留。按组件名构建时，构建器依据类选择器与": "Reservado como alias compatible. Al construir por nombre de componente, el constructor depende del selector de clase y",
  "作者可使用的 309 个属性被划分为上方行为契约中的 66 个行为入口、166 个结构/动作选择器和 77 个附加配置属性；另有 27 个由运行时维护的状态属性。状态属性可能同时作为初始配置读取，但作者可用的前三组彼此互斥，不会重复计数。": "Las 309 propiedades disponibles para el autor se dividen en 66 entradas de comportamiento en el contrato de comportamiento anterior, 166 selectores de estructura/acción y 77 propiedades de configuración adicionales; También hay 27 propiedades de estado mantenidas por el tiempo de ejecución. Las propiedades de estado se pueden leer simultáneamente como configuración inicial, pero los primeros tres conjuntos disponibles para el autor son mutuamente excluyentes y no se cuentan dos veces.",
