  "Axe 门禁阻断所选 WCAG A/AA 规则检测到的全部违规，不按 impact 降级放行，并输出规则、节点选择器、HTML 与修复摘要。自动化不能代替人工屏幕阅读器测试；正式产品仍应使用 NVDA / JAWS / VoiceOver 完成关键任务走查。": "Axe La puerta bloquea todas las violaciones detectadas por las reglas WCAG A/AA seleccionadas, las pasa sin rebajas por impacto, y produce la regla, selector de nodos, HTML, y resumen de remediación. La automatización no puede reemplazar las pruebas del lector de pantallas humanas; los productos de producción todavía deben utilizar NVDA/JAWS/VoiceOver para pasarelas críticas por misión.",
  "Axe WCAG 2 A/AA 全部自动违规归零，并覆盖键盘与焦点恢复、RTL、Reduced Motion、Forced Colors。": "Axe WCAG 2 A/AA Todas las infracciones automáticas ponen a cero y cubren la recuperación de enfoque y teclado, RTL, movimiento reducido, colores forzados.",
