  "Gardener — 为所有界面准备好的 CSS 基础设施": "Gardener: infraestructura CSS lista para todas las interfaces",
  "gardener / workspace / overview": "jardinero/espacio de trabajo/descripción general",
  "Gardener 把基础 CSS、交互组件、业务配方、桌面端适配与机器可读清单放进同一套系统。人可以直接开发，AI 可以准确选用，无需每次重新组织样式。": "Gardener reúne CSS básico, componentes interactivos, recetas comerciales, adaptación de escritorio y manifiestos legibles por máquina en un solo sistema. Las personas pueden desarrollarse directamente y la IA puede seleccionarlo y usarlo con precisión sin tener que reorganizar el estilo cada vez.",
  "Gardener 可以只使用 CSS，也可以加载零依赖运行时获得交互行为。完整包默认包含所有主题、组件和工具类。": "Gardener puede usar solo CSS o cargar un tiempo de ejecución sin dependencia para un comportamiento interactivo. El paquete completo incluye todos los temas, componentes y clases de herramientas de forma predeterminada.",
  "Gardener 是面向人类开发者与 AI 页面生成器的通用 CSS、Vue 3、React、AngularJS 与 Blazor 组件、页面配方及桌面应用基础设施。": "Gardener es componentes universales de CSS, Vue 3, React, AngularJS y Blazor, recetas de páginas e infraestructura de aplicaciones de escritorio para desarrolladores humanos y creadores de páginas de IA.",
  "Gardener 首页": "Página principal de Gardener",
  "Gardener 完整文档：CSS、Vue 3、React、AngularJS、Blazor、主题、Token、工具类、506 个组件、运行时、完整页面、AI 页面生成及桌面端适配。": "Documentación completa de Gardener: CSS, Vue 3, React, AngularJS, Blazor, tema, Token, clase de herramienta, 506 componentes, tiempo de ejecución, página completa, generación de páginas AI y adaptación de escritorio.",
  "Gardener 为 AI 提供五层事实来源：公共 API 清单回答“允许使用什么稳定名称与入口”，能力清单回答“行业常规能力是否实现”，组件清单回答“有什么”，工具类清单回答“精确类名是什么”，配方清单回答“复杂页面怎样开始”。": "Gardener proporciona cinco capas de fuentes verdaderas para la IA: la lista de API pública responde \"qué nombres y entradas estables se permiten usar\", la lista de capacidades responde \"si se implementan las capacidades regulares de la industria\", la lista de componentes responde \"qué hay allí\", la lista de clases de herramientas responde \"cuál es el nombre de clase exacto\" y la lista de recetas responde \"cómo iniciar una página compleja\".",
  "Gardener 文档": "Gardener Documentación",
  "Gardener 移动端组件预览": "Vista previa del componente móvil Gardener",
  "Gardener 以 24 栅格作为企业后台、CMS 和精细表单的主兼容协议，同时通过": "Gardener utiliza 24 ráster como principal protocolo compatible para backend empresarial, CMS y formularios finos, al pasar",
