  "Release 构建为 0 警告、0 错误；506 个组件全部经过真实静态 SSR。浏览器矩阵覆盖 Chromium、Firefox、WebKit、桌面与移动视口、键盘和 Axe WCAG A/AA；CI 强制 Firefox。 NuGet 使用隔离缓存真实发布消费应用，并验证静态 Web Assets endpoint manifest；另有独立 .NET 11 Preview 包消费者。程序集实测 343,552 B，43 个静态资源共 7,608,327 B，CSS gzip 139,269 B，runtime gzip 25,989 B，Blazor bridge gzip 2,054 B，nupkg 约 1.22 MiB、低于 6,000,000 B 硬上限；全部低于硬预算且 DLL/XML 可复现。": "Versión de versión con 0 advertencias, 0 errores; 506 componentes pasaron todos SSR estático verdadero. Browser Matrix cubre Chromium, Firefox, WebKit, ventanas gráficas de escritorio y móviles, teclado y Axe WCAG A/AA; CI exige Firefox. NuGet utiliza una caché aislada para publicar aplicaciones de consumo y validar manifiestos de puntos finales de activos web estáticos; También hay un consumidor de paquete de vista previa .NET 11 independiente. El ensamblaje medido es 343.552 B, 43 recursos estáticos totalizan 7.608.327 B, CSS gzip 139.269 B, tiempo de ejecución gzip 25.989 B, Blazor bridge gzip 2.054 B, nupkg aproximadamente 1,22 MiB, por debajo del límite estricto de 6.000.000 B; todo por debajo del presupuesto estricto y DLL/XML reproducible.",
