  "Stack、Cluster、Sidebar、Switcher、Reel、Media Object、Masonry、Bento 等经典模式已经固化为内在响应接口。AI 只需选择意图和少量变量，无需重新发明 Flex、Grid、溢出与安全区规则。": "Los patrones clásicos como Stack, Cluster, Sidebar, Switcher, Reel, Media Object, Masonry y Bento se han solidificado en interfaces de respuesta intrínsecas. La IA solo necesita elegir la intención y algunas variables, no es necesario reinventar las reglas Flex, Grid, desbordamiento y área segura.",
